15	func recapLoadErrorMessage(err error) string {
16		if errors.Is(err, context.Canceled) {
17			return "Recap request was canceled."
18		}
19		if errors.Is(err, context.DeadlineExceeded) {
20			return fmt.Sprintf("Recap request timed out. Check your internet connection and retry. Details: %v", err)
21		}
22	
23		var apiErr *api.HTTPError
24		if errors.As(err, &apiErr) {
25			detail := recapErrorDetail(apiErr)
26			switch apiErr.StatusCode {
27			case http.StatusUnauthorized:
28				return "Run `entire login` to re-authenticate."
29			case http.StatusBadRequest:
30				return "Entire sent an invalid recap time range. Please update Entire CLI and retry. Details: " + detail
31			case http.StatusNotFound:
32				return "entire.io could not find your account. Run `entire logout` then `entire login`; if it still fails, contact Entire support. Details: " + detail
33			default:
34				if apiErr.StatusCode >= http.StatusInternalServerError {
35					return "entire.io could not build the recap. Please retry in a moment; if it still fails, contact Entire support. Details: " + detail
36				}
37				return err.Error()
38			}
39		}
40		if host, ok := dnsNotFoundHost(err); ok {
41			return fmt.Sprintf("Could not resolve API host %q (DNS lookup failed). Check ENTIRE_API_BASE_URL — the host may be misspelled or the env var may be pointing at a non-existent server. Details: %v", host, err)
42		}
43		if isRecapNetworkError(err) {
44			return fmt.Sprintf("Could not reach entire.io. Check your internet connection and ENTIRE_API_BASE_URL if you use a custom API host. Details: %v", err)
45		}
46		return err.Error()
47	}
48	
49	// dnsNotFoundHost reports an NXDOMAIN-style failure, distinguishing "host
50	// doesn't exist" from generic connectivity loss.
51	func dnsNotFoundHost(err error) (string, bool) {
52		var dnsErr *net.DNSError
53		if errors.As(err, &dnsErr) && dnsErr.IsNotFound {
54			return dnsErr.Name, true
55		}
56		return "", false
57	}
58	
59	func recapErrorDetail(err *api.HTTPError) string {
60		if strings.TrimSpace(err.Message) != "" {
61			return fmt.Sprintf("HTTP %d: %s", err.StatusCode, err.Message)
62		}
63		if text := http.StatusText(err.StatusCode); text != "" {
64			return fmt.Sprintf("HTTP %d: %s", err.StatusCode, text)
65		}
66		return fmt.Sprintf("HTTP %d", err.StatusCode)
67	}
68	
69	func isRecapNetworkError(err error) bool {
70		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
71			return false
72		}
73		var urlErr *url.Error
74		if errors.As(err, &urlErr) {
75			return true
76		}
77		var dnsErr *net.DNSError
78		return errors.As(err, &dnsErr)
79	}
