package auth

import (
	"context"
	"fmt"
	"net"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/tokenstore"
)

// Repro: a context whose core is no longer listening (stale local dev core).
func TestZZRepro_DeadCore(t *testing.T) {
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	// Grab a port nobody is listening on.
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := ln.Addr().String()
	_ = ln.Close()
	coreURL := "https://" + addr

	svc := tokenstore.CoreKeyringService(coreURL)
	expired := makeJWT(t, fmt.Sprintf(`{"iss":%q,"handle":"alice","exp":%d}`, coreURL, time.Now().Add(-time.Hour).Unix()))
	if err := tokenstore.Set(svc, "alice", expired+tokenstore.TokenExpirationSeparator+"0"); err != nil {
		t.Fatal(err)
	}
	if err := tokenstore.Set(tokenstore.RefreshService(svc), "alice", "entr_refresh"); err != nil {
		t.Fatal(err)
	}

	c := &contexts.Context{Name: "local", CoreURL: coreURL, Handle: "alice", KeychainService: svc}
	provider, err := NewRefreshingLoginProvider(c, nil, true)
	if err != nil {
		t.Fatal(err)
	}
	_, err = provider(context.Background())
	t.Fatalf("REPRO MESSAGE:\n  %v", err)
}

